// Single source of truth for the "What's New" popup (WhatsNewPopup.jsx) and
// the "What's New" sub-tab in GuideTab.jsx -- both render this same list, so
// there's only one place to update when something ships.
//
// Add a new entry to the TOP of this array whenever a user-visible change is
// released. Every entry carries a `summary` -- ONE plain-English sentence of
// the user-visible outcome ("Social Security now starts at the age you
// chose, for single filers"), no statute numbers, no function names. The
// popup and the Guide lead with the summary and keep the detailed `items`
// behind a per-entry Details expander (changelog 106), so the summary is
// what most users will ever read: write it for them, keep the depth in
// `items`. `id` must be a strictly increasing integer (never reused, never
// skipped backwards) -- it's what WhatsNewPopup compares against a visitor's
// last-seen id in localStorage to figure out whether they have unread
// updates, the same pattern calculator.js's INPUTS_SCHEMA_VERSION uses for
// migrations. Bump it by 1 each time; the actual number has no other
// meaning.
//
// Don't stop here -- see the "Documentation checklist" in DEVELOPMENT.md. A new
// feature/fix usually also needs a matching update in GuideTab.jsx (the
// prose walkthrough) and InputReference.jsx (the Input Dictionary), not just
// an entry here.
//
// A release note may set `tone: 'notice' | 'action' | 'success'` for a
// colored background wherever it renders (ChangelogEntry.jsx's
// CHANGELOG_TONES); omit for the default look. To send a STANDALONE message
// to users -- timed, queueable, shown to first-time visitors too -- add an
// entry to config/announcements.js instead; those ride the same What's New
// popup but are kept out of this permanent release-notes history on purpose.
