    title: "Washington plans switch to the Washington tax choice",
    tone: 'notice',
    summary: "A plan that lives in Washington but was saved on the Tax-Free State choice now moves to the Washington choice by itself, so its capital gains and income taxes are counted.",
    items: [
      "**Done for you.** If your State of Residence is Washington and your plan was on Tax-Free State, it now uses Washington, including any move to Washington in your residency timeline. The capital gains tax and, from 2028, the income tax on income over $1 million are counted from now on.",
      "**Your own choices stay.** A Washington plan you set to a flat rate on purpose is left as it is, and plans in every other state are unchanged.",
    ],
