      "**Checked fields.** A field keeps its last good value and explains the range when you type something it cannot use: a birth year of 3000, a claiming age of 99, \u201c1e9\u201d, or \u201c48.000,50\u201d. Clearing a balance now counts as $0; before, it could show a nest egg of two billion dollars. Money fields show thousands commas everywhere.",
