      "**Older backup files.** A backup made before plans carried a version number restored the default plan instead of yours. It restores yours now.",
      "**All or nothing.** A restore checks the whole file first and writes nothing if any part cannot be used, so a damaged file can no longer leave the app half-restored or unable to open. Live Pricing links in a file are restored only if you turn that on, and only Google addresses are accepted.",
      "**Erase everything on this device.** Preferences \u2192 Your Data has a control that removes your plan, scenarios, holdings, checklist, Life Plan, Premium key and preferences from this browser after you type ERASE. Reset Plan to Defaults still resets only the active plan.",
      "**When saving fails.** If this browser\u2019s storage is full, a banner says your latest change was not saved. If you change your plan in another tab, this tab stops saving over it and offers the newer version. If the app ever fails to open, the error screen offers Download my data.",
