      '**One list.** The chart\u2019s income layers (Standard Deduction, Wages, Pension, Taxable SS, Forced RMDs, Pre-Tax Draws, Roth Conversions) are defined once and drawn from that list by the bars, the legend beneath and the hover card, so the three can no longer call the same figure by different names.',
