      "**One extra rule for IRMAA, because it is not a tax bracket.** IRMAA is assessed on your MAGI from *two years earlier*, so only income from age 63 onward can ever produce a surcharge. A $400,000 salary at 45 no longer drags in tiers you will never face. And if your income never reaches the first threshold you still get that one line \u2014 \u201chow much room do I have before this starts costing me\u201d is the question the toggle exists to answer.",
      "**Correction to what was said last time.** The previous note claimed a manual choice stops the auto-defaults \u201cpermanently.\u201d It did not \u2014 the state was in memory only, so a page refresh wiped it and the defaults came back. It is persisted now, so it genuinely holds across reloads.",
