      "**Tax & Estate, Risk & Stress, and Saving & Exporting** now use the same collapsible structure as Plan Settings \u2014 one entry per sub-tab, closed by default. The worst single paragraph in Saving & Exporting ran **2,082 characters**; Tax & Estate had one at 1,449 and Risk & Stress one at 1,173. Nothing in the file now exceeds 900.",
      "**Two sub-tabs were undocumented.** Risk & Stress has a fourth sub-tab, **Guardrails vs Fixed Withdrawals**, that the guide never mentioned \u2014 including the thing you most need to know before reading it, which is that guardrails only change anything in a year with a negative return, so comparing them on versus off is meaningless outside a crash. Tax & Estate's new **Documents Checklist** was missing too. Both are covered now, and both section subtitles were listing three sub-tabs when there are four.",
      "The Backup Everything entry in particular was one unbroken block covering what the file contains, what restore does, the one exception for Detailed Holdings, where to store it, and why to treat it like a password file. Five distinct things a reader needs at five different moments, in one paragraph. It is five short paragraphs now, and it leads with the part that matters: everything lives only in this browser, and a browser reset takes it with nothing to recover from.",
