      "One honest caveat, stated in the panel itself: the headline figure is heir *income tax*, not net inherited. This model grows an inherited IRA across the 10-year withdrawal window while treating Roth and Taxable as paid out at once, so it credits pre-tax with growth the other two don't get \u2014 which understates the gain from giving pre-tax away. The tax figure is the clean one.",
      "**Proportional stays the default**, so every existing saved plan produces exactly the same numbers as before. The guide previously said this targeting wasn't modeled; that text has been corrected rather than left to rot.",
