      "**Plan Settings, broken up.** That section of the guide had grown into two paragraphs of roughly 7,000 and 12,000 characters \u2014 single blocks running forty-plus lines on screen, each covering five different sub-tabs at once. It is now one collapsible entry per sub-tab, in the same order the sub-tabs actually appear in the app, all closed by default. What was a wall of text is now a nine-item table of contents you can scan.",
      "**Two things it was getting wrong.** The intro said Plan Settings was \u201cdivided into four sub-tabs\u201d \u2014 there are nine. And **Assumptions & Risk** was described in two separate bullets, in two different places, because the text had been appended to over time rather than reorganized. Both fixed by mirroring the app's own navigation instead of maintaining a second, drifting grouping.",
      "**Detailed Holdings has its own section now.** Its six sub-tabs were documented inside a single bullet about Plan Settings \u2192 Balances & Debt, which is where the *link* to it lives \u2014 roughly 9,000 characters of premium-feature documentation buried inside a paragraph about entering account balances. It is now section 4, with its own collapsible entry per sub-tab and a closing note on the four plan fields it can drive.",
