      'Also corrected the Guide\'s "Saving & Exporting" section, which described the Sidebar\'s "Download Config" button as supporting drag-and-drop restore -- it never did; that button is export-only. The Guide now documents Cloud Backup & Sync\'s Export/Import JSON as the actual restore mechanism.',
