      'Why: mutual funds strike one NAV a day through their transfer agent rather than trading, so the original stock/ETF data source (Massive) simply has nothing for them, no matter how the ticker is formatted -- that\'s different from an outage or a typo\'d symbol. A second data source (EODHD) that does carry daily fund NAV now fills that specific gap; everything else about the feature (opt-in Premium Access Key, previous-day-only prices, ticker-symbol-only requests) is unchanged.',
      'Since a fund\'s NAV can\'t change more than once a day, a given fund ticker is fetched from EODHD at most once per day no matter how many times Refresh Prices is clicked -- the result is reused for the rest of that day rather than re-querying.',
