      'Each holding can now optionally record a Frequency (Monthly/Quarterly/Semi-Annual/Annual/Irregular) -- shown as an estimated per-payment amount, and a Distribution Character (Qualified Dividend/Ordinary Dividend/Long-Term or Short-Term Capital Gain Distribution/Return of Capital/Mixed), shown as a new totals breakdown. Both are purely informational for now, same as the existing account-level breakdown -- not read by the tax engine.',
      'Distribution Character is a deliberately separate concept from Tax Treatment: Tax Treatment is about the account (does a distribution get taxed this year at all), Distribution Character is about how a taxable-account distribution is taxed when it does. A fund can pay a real mix across a year -- "Mixed / Fund-Dependent" covers that instead of forcing one wrong label.',
      'Dividends sub-tab now also shows Yield on Cost (trailing dividend/share over your average buy price, distinct from Yield which uses current price) and an Avg. Monthly Cash Flow card (the annual total spread evenly -- not tied to actual payment months, since no payment-schedule data is tracked).',
