      'This is a third, complementary way to fill out a plan alongside the existing 6-step "Interactive Setup Wizard" (fast, minimal, shown to new visitors) and Plan Settings (exhaustive, always-visible, for someone who already knows exactly what they want to change). All three read and write the exact same underlying plan data, so switching between them mid-setup never loses anything. Progress (which sections you\'ve visited) is remembered locally so you can pick up where you left off.',
