      'The "Print / PDF Report" (sidebar) now includes three new sections beyond the existing headline metrics, Action Plan, and Year-by-Year table: a "Tax & Roth Conversion Analysis" (lifetime taxes paid, IRMAA surcharges, forced RMDs, and — if a Roth Conversion Strategy is active — the total amount converted and its effective tax cost), an "Estate & Legacy Summary" (gross/net inheritance, state and federal estate tax, and a per-heir breakdown table), and a "Risk Analysis" section (Monte Carlo success probability and legacy percentiles if you\'ve run the 1,000-trial simulation, the Minimum Required Rate of Return vs. your assumed return, and whether a Historical Stress Test is currently configured).',
