      'Shows that minimum alongside your actual assumed return and the "cushion" between them, so you can see at a glance how much room your plan has to underperform. Flags plans that are already infeasible even at a very optimistic 30%/yr average return (spending, retirement age, or savings need to change instead of chasing a higher return) as well as plans so well-funded the search floor (-10%/yr) isn\'t low enough to matter.',
